disabled ?>></label><label class="toggle-field"><span>وضعیت حساب کاربری</span><input type="checkbox" name="is_active" value="1" <?= !isset($form['is_active']) || !empty($form['is_active']) ? 'checked' : '' ?> <?= $disabled ?>><strong>امکان ورود به پنل مدیریت فعال باشد</strong></label></div></section><section class="admin-panel editor-panel"><div class="panel-heading"><div><p class="admin-eyebrow">استثناها (Overrides)</p><h2 id="user-overrides-heading">تخصیص دسترسی‌های خاص به کاربر</h2></div></div><p id="user-overrides-help" class="form-note">به طور پیش‌فرض، کاربر دسترسی‌های مربوط به نقش انتخابی خود را به ارث می‌برد. در صورت لزوم می‌توانید دسترسی مشخصی را صراحتاً مجاز یا ممنوع کنید.</p><div class="permission-groups" role="group" aria-labelledby="user-overrides-heading" aria-describedby="user-overrides-help"><?php foreach ($grouped as $module => $items): ?><fieldset class="permission-group"><legend><?= e($translatedModules[$module] ?? ucwords(str_replace(array('_', '-'), ' ', $module))) ?></legend><?php foreach ($items as $permission): $code = (string) $permission['code']; $effect = $overrides[$code] ?? ''; ?><div class="override-item"><strong><?= e($permission['title']) ?></strong><small><?= e($code) ?></small><select name="overrides[<?= e($code) ?>]" aria-label="استثنا برای <?= e($permission['title']) ?>" <?= $disabled ?>><option value="">ارث‌بری از نقش</option><option value="allow" <?= $effect === 'allow' ? 'selected' : '' ?>>مجاز صریح (Allow)</option><option value="deny" <?= $effect === 'deny' ? 'selected' : '' ?>>ممنوع صریح (Deny)</option></select></div><?php endforeach; ?></fieldset><?php endforeach; ?></div></section></main></div><?php if (empty($read_only)): ?><div class="editor-submit"><a class="admin-cancel-link" href="<?= e(admin_url('/users')) ?>">انصراف</a><button class="admin-primary-button" type="submit">ذخیره عضو تیم <span aria-hidden="true">→</span></button></div><?php endif; ?></form>
